from robot.libraries.BuiltIn import BuiltIn
from robot.running import EXECUTION_CONTEXTS


class LibrarySearchOrder(object):
    LIBRARIES = []

    @staticmethod
    def set_library_search_order(path):
        if EXECUTION_CONTEXTS.current:
            if path in LibrarySearchOrder.LIBRARIES:
                LibrarySearchOrder.LIBRARIES.remove(path)
            LibrarySearchOrder.LIBRARIES.insert(0, path)

            BuiltIn().set_library_search_order(*LibrarySearchOrder.LIBRARIES)
